372	     * @param owner the newly mapped owner to canonicalize
373	     */
374	    private void normalizeOwnerFields(Owner owner) {
375	        // Normalize the address on create so it is stored and returned in canonical form and every
376	        // later comparison (household duplicate detection and the shared household id) uses it.
377	        // A value that is blank after normalization is rejected with 400.
378	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
379	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
380	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
381	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
382	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
383	        // Store the (already syntactically validated) email lower-cased so it is persisted and
384	        // returned in canonical form. A missing email is left untouched.
385	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
386	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
387	        // canonicalization so the comparison sees the lower-cased value.
388	        rejectDisposableEmailDomain(owner.getEmail());
389	        // Validate the optional postcode against the fixed range for the city's region. A postcode
390	        // is checked only when present (it is optional); one out of range for the city's region is
391	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
392	        // value is left unchanged.
393	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
394	        // Reject a supplied registration date that is later than the server's current date with
395	        // 400, before any defaulting or business-day adjustment, so a future date is never
396	        // persisted regardless of how the roll-forward would move it.
397	        rejectFutureRegistrationDate(owner.getRegistrationDate());
398	        // Default the registration date to the server's current date when the client did not
399	        // supply one, then roll the effective date forward to a business day so a Saturday or
400	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
401	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
402	        // date-derived field (such as the membership number's year segment) and the per-day
403	        // create-limit are computed from.
404	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
