411	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
412	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
413	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
414	     * domain part is left untouched.
415	     *
416	     * @param email the owner's canonicalized email, or {@code null} when absent
417	     */
418	    private void rejectDisposableEmailDomain(String email) {
419	        if (email == null) {
420	            return;
421	        }
422	        int at = email.lastIndexOf('@');
423	        if (at < 0) {
424	            return;
425	        }
426	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
427	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
428	            throw new DisposableEmailException(
