456	     * @return the same date if it is a weekday, otherwise the following Monday
457	     */
458	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
459	        java.time.LocalDate adjusted = date;
460	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
461	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
462	            adjusted = adjusted.plusDays(1);
463	        }
464	        return adjusted;
465	    }
